<?php require_once 'config.php'; $page_title='Bolsas de estudo | Kuntima'; $pdo=db(); $q=trim($_GET['q']??''); $level=trim($_GET['nivel']??''); $sql="SELECT * FROM scholarships WHERE status='published' AND (deadline IS NULL OR deadline>=CURDATE())"; $args=[]; if($q!==''){$sql.=' AND (title LIKE ? OR organization LIKE ? OR field LIKE ? OR country LIKE ?)';$like='%'.$q.'%';array_push($args,$like,$like,$like,$like);}if($level!==''){$sql.=' AND study_level=?';$args[]=$level;}$sql.=' ORDER BY deadline IS NULL, deadline';$st=$pdo->prepare($sql);$st->execute($args);$items=$st->fetchAll(); require 'includes/header.php'; ?>
<div class="page-heading"><span class="eyebrow" style="color:var(--green)">Encontra a tua oportunidade</span><h1>Bolsas de estudo</h1><p>Pesquisa oportunidades por nome, instituição, área ou país.</p></div><form class="filters" method="get"><input name="q" value="<?=e($q)?>" placeholder="Ex.: engenharia, Portugal, Fundação…"><select name="nivel"><option value="">Todos os níveis</option><?php foreach(['Ensino secundário','Licenciatura','Mestrado','Doutoramento','Mestrado e Doutoramento'] as $v): ?><option <?= $level===$v?'selected':'' ?> value="<?=e($v)?>"><?=e($v)?></option><?php endforeach; ?></select><button class="btn-primary" type="submit">Pesquisar</button><a class="btn-small" href="bolsas.php">Limpar</a></form><p class="muted"><?=count($items)?> oportunidade(s) encontrada(s)</p><?php if($items): ?><div class="grid"><?php foreach($items as $s): ?><article class="card"><div class="card-top"><div class="org-icon">🎓</div><span class="tag"><?=e($s['funding_type'])?></span></div><h3><?=e($s['title'])?></h3><div class="muted"><?=e($s['organization'])?> · <?=e($s['country'])?></div><p><?=e(mb_strimwidth($s['description'],0,145,'…','UTF-8'))?></p><div class="card-meta"><span><?=e($s['study_level'])?></span><span><?= $s['deadline']?'Prazo: '.e(date('d/m/Y',strtotime($s['deadline']))):'Prazo a confirmar' ?></span></div><a class="btn-primary" href="bolsa.php?id=<?=$s['id']?>">Ver detalhes</a></article><?php endforeach; ?></div><?php else: ?><div class="empty">Não encontrámos bolsas com esses critérios. Tenta outra pesquisa.</div><?php endif; ?><?php require 'includes/footer.php'; ?>
